# Compute which albums have all songs downloaded and total duration >= 900 seconds
downloaded_durations = {song['song_id']: song['duration'] for song in downloaded_songs}
qualifying_albums = []
for album in all_albums:
    song_ids = album['song_ids']
    # Check if all songs are downloaded
    if all(sid in downloaded_durations for sid in song_ids):
        total_duration = sum(downloaded_durations[sid] for sid in song_ids)
        if total_duration >= 900:
            qualifying_albums.append((album['album_id'], album['title'], total_duration))
print("Qualifying albums (all songs downloaded, total duration >= 900s):")
print(qualifying_albums)

